from __future__ import annotations

import json
from dataclasses import dataclass
from datetime import datetime
from pathlib import Path
from typing import Any, Mapping, Sequence

from research_workbench.artifacts.integrity import hash_bytes, resolve_within_root
from research_workbench.execution.host import (
    ValidatedExecutionView,
    load_resolved_execution_view,
)
from research_workbench.execution.runtime_bundle import ValidatedRuntimeBundle
from research_workbench.io import load_document_bytes
from research_workbench.observability.trace import validate_attempt_trace
from research_workbench.validation.schemas import SchemaCatalog


@dataclass(frozen=True, slots=True)
class CloseoutPin:
    path: str
    sha256: str


@dataclass(frozen=True, slots=True)
class ValidatedGenericReceipt:
    project_root: Path
    receipt_path: Path
    receipt_sha256: str
    document: Mapping[str, Any]


class GenericCloseoutValidationError(ValueError):
    pass


def _normalized_hash(value: object) -> str | None:
    if not isinstance(value, str):
        return None
    normalized = value.lower().removeprefix("sha256:")
    if len(normalized) != 64:
        return None
    try:
        int(normalized, 16)
    except ValueError:
        return None
    return normalized


def _plain(value: Any) -> Any:
    if isinstance(value, Mapping):
        return {key: _plain(item) for key, item in value.items()}
    if isinstance(value, (list, tuple)):
        return [_plain(item) for item in value]
    return value


def _load_pin(
    root: Path,
    pin: CloseoutPin,
    *,
    kind: str,
    catalog: SchemaCatalog,
) -> tuple[Path, Mapping[str, Any]]:
    path = resolve_within_root(root, pin.path)
    if path is None or not path.is_file():
        raise GenericCloseoutValidationError(f"{kind} input is missing or outside project root")
    content = path.read_bytes()
    if _normalized_hash(pin.sha256) != hash_bytes(content):
        raise GenericCloseoutValidationError(f"{kind} input hash mismatch")
    try:
        document = load_document_bytes(path, content)
    except Exception as exc:
        raise GenericCloseoutValidationError(f"{kind} input is not parseable") from exc
    errors = catalog.validate(kind, document)
    if errors:
        raise GenericCloseoutValidationError(f"{kind} input is schema-invalid")
    if not isinstance(document, Mapping):
        raise GenericCloseoutValidationError(f"{kind} input must be an object")
    return path, document


def _file_ref(root: Path, path: Path) -> dict[str, str]:
    return {
        "path": path.relative_to(root).as_posix(),
        "sha256": hash_bytes(path.read_bytes()),
    }


def _validate_artifact_refs(root: Path, artifacts: Sequence[Mapping[str, Any]]) -> None:
    for artifact in artifacts:
        path = resolve_within_root(root, artifact.get("path", ""))
        if path is None or not path.is_file():
            raise GenericCloseoutValidationError("Host artifact is missing or outside project root")
        if _normalized_hash(artifact.get("sha256")) != hash_bytes(path.read_bytes()):
            raise GenericCloseoutValidationError("Host artifact hash mismatch")


def _timestamp(value: object, field: str) -> datetime:
    if not isinstance(value, str):
        raise GenericCloseoutValidationError(f"{field} is not an RFC3339 timestamp")
    try:
        parsed = datetime.fromisoformat(value.replace("Z", "+00:00"))
    except ValueError as exc:
        raise GenericCloseoutValidationError(f"{field} is not an RFC3339 timestamp") from exc
    if parsed.tzinfo is None:
        raise GenericCloseoutValidationError(f"{field} lacks a timezone")
    return parsed


def _validate_host_view_closure(
    host: Mapping[str, Any], view: ValidatedExecutionView
) -> None:
    expected_view_ref = {
        "ref": f"{view.document['view_id']}@r{view.document['revision']}",
        "path": view.view_path.relative_to(view.project_root).as_posix(),
        "sha256": view.view_sha256,
    }
    if (
        host.get("view_ref") != expected_view_ref
        or host.get("runtime_bundle_ref") != view.document.get("runtime_bundle_ref")
        or host.get("task_ref") != view.document.get("task_ref")
        or host.get("execution_scope") != _plain(view.document.get("execution_scope"))
    ):
        raise GenericCloseoutValidationError(
            "Host report View/Bundle/Task/execution-slice lineage mismatch"
        )
    status = host.get("status")
    phase = host.get("execution_phase")
    actual_present = "actual_binding" in host or "actual_supply_report_ref" in host
    if status == "completed":
        if phase != "post-call":
            raise GenericCloseoutValidationError("completed Host report is not post-call")
        if host.get("actual_binding") != _plain(view.document.get("binding")):
            raise GenericCloseoutValidationError(
                "completed Host actual binding does not equal frozen View binding"
            )
        if host.get("actual_supply_report_ref") != view.document.get(
            "selected_supply_report_ref", {}
        ).get("ref"):
            raise GenericCloseoutValidationError(
                "completed Host actual Supply does not equal frozen View selected Supply"
            )
    elif status == "blocked":
        if phase != "preflight-blocked" or actual_present:
            raise GenericCloseoutValidationError(
                "preflight-blocked Host report must not contain actual execution binding"
            )
    elif status == "failed":
        if phase == "post-call":
            if not isinstance(host.get("actual_binding"), Mapping) or not isinstance(
                host.get("actual_supply_report_ref"), str
            ):
                raise GenericCloseoutValidationError(
                    "post-call failed Host report must preserve actual binding and Supply"
                )
            diagnostic_code = host.get("diagnostic", {}).get("code")
            if (
                diagnostic_code == "HOST-ACTUAL-BINDING-DRIFT"
                and host.get("actual_binding") == _plain(view.document.get("binding"))
            ):
                raise GenericCloseoutValidationError(
                    "Host binding-drift diagnostic is not supported by actual binding facts"
                )
            if (
                diagnostic_code == "HOST-ACTUAL-SUPPLY-DRIFT"
                and host.get("actual_supply_report_ref")
                == view.document.get("selected_supply_report_ref", {}).get("ref")
            ):
                raise GenericCloseoutValidationError(
                    "Host Supply-drift diagnostic is not supported by actual Supply facts"
                )
        elif phase == "driver-exception":
            if actual_present:
                raise GenericCloseoutValidationError(
                    "driver-exception Host report cannot invent actual binding"
                )
        else:
            raise GenericCloseoutValidationError("failed Host report has an invalid phase")
    if _timestamp(host.get("completed_at"), "host.completed_at") < _timestamp(
        host.get("started_at"), "host.started_at"
    ):
        raise GenericCloseoutValidationError("Host report time interval is reversed")


def _trace_relative_pin(
    root: Path, trace_path: Path, reference: Mapping[str, Any]
) -> CloseoutPin:
    path = resolve_within_root(trace_path.parent, reference.get("path", ""))
    if path is None:
        raise GenericCloseoutValidationError("Execution Trace child reference escapes its archive")
    try:
        relative = path.relative_to(root).as_posix()
    except ValueError as exc:
        raise GenericCloseoutValidationError(
            "Execution Trace child reference escapes project root"
        ) from exc
    return CloseoutPin(relative, str(reference.get("sha256", "")))


def _load_trace_events(
    root: Path, trace_path: Path, trace: Mapping[str, Any]
) -> tuple[Mapping[str, Any], ...]:
    ledger = trace.get("event_ledger", {})
    path = resolve_within_root(trace_path.parent, ledger.get("path", ""))
    if path is None or not path.is_file():
        raise GenericCloseoutValidationError("Execution Trace event ledger is missing")
    content = path.read_bytes()
    if _normalized_hash(ledger.get("sha256")) != hash_bytes(content):
        raise GenericCloseoutValidationError("Execution Trace event ledger hash mismatch")
    try:
        events = tuple(
            json.loads(line)
            for line in content.decode("utf-8").splitlines()
            if line.strip()
        )
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise GenericCloseoutValidationError("Execution Trace event ledger is not parseable") from exc
    if len(events) != ledger.get("event_count") or not all(
        isinstance(item, Mapping) for item in events
    ):
        raise GenericCloseoutValidationError("Execution Trace event ledger count/shape mismatch")
    return events


def _validate_trace_execution_records(
    root: Path,
    trace_path: Path,
    trace: Mapping[str, Any],
    host: Mapping[str, Any],
    *,
    catalog: SchemaCatalog,
) -> None:
    scope_records: list[Mapping[str, Any]] = []
    execution_facts: list[Mapping[str, Any]] = []
    for reference in trace.get("decision_refs", ()):
        if not isinstance(reference, Mapping):
            continue
        pin = _trace_relative_pin(root, trace_path, reference)
        path = resolve_within_root(root, pin.path)
        if path is None or not path.is_file():
            raise GenericCloseoutValidationError("Trace decision reference is missing")
        content = path.read_bytes()
        if _normalized_hash(pin.sha256) != hash_bytes(content):
            raise GenericCloseoutValidationError("Trace decision reference hash mismatch")
        document = load_document_bytes(path, content)
        if not isinstance(document, Mapping):
            continue
        if document.get("record_kind") == "execution-scope-binding":
            scope_records.append(document)
        elif document.get("record_kind") == "actual-execution-binding":
            errors = catalog.validate("execution_trace_fact", document)
            if errors:
                detail = "; ".join(f"{item.pointer}: {item.message}" for item in errors)
                raise GenericCloseoutValidationError(
                    "Execution Trace actual-binding fact is schema-invalid: " + detail
                )
# 模块 03：Agent 运行模型

## 1. 目标

定义主 Agent 与子 Agent 的职责、Agent Profile、委派条件和执行映射。项目保持 API 与平台中立；黄毅维护 API session 及其测试，路诚钺维护进入任何执行路径之前的 Task、Mode、Skill、读取、Trace 和返回边界。

## 2. 主 Agent Charter

主 Agent 负责：

- 维护当前问题、约束、决定、风险和任务索引；
- 判断任务是否值得委派；
- 创建 Task Packet 并请求能力解析；
- 比较 Handoff、处理冲突和识别 Human Gate；
- 维护并执行当前 Claim ceiling，提出 Claim 升级/降级候选，并识别 promotion 所需的 Evidence、
  Method rule 与 Human Gate；不得自行批准高风险或主要 Claim promotion；
- 控制执行成本和停止时机；
- 在上下文压力前写 Main State 并主动 rollover。
- 给出目标路径和初始内容允许集；需要扩大正文读取范围时负责修订 Task。

主 Agent 不负责：

- 长期阅读和保存大规模原始材料；
- 直接吞入日志、数据集、整本论文或所有 Skill 正文；
- 亲自完成所有检索、编程、仿真和复核；
- 用自然语言摘要替代正式工件；
- 默认建立多轮 Agent 互审。
- 把“能访问工作区”解释为“可以读取全部仓库正文”。

## 3. Agent Profile

Agent Profile 是运行容器配置，不是研究方法。建议字段：

```yaml
schema_version: 0.1.0
agent_profile_id: evidence-scout
version: 0.1.0
purpose: read-heavy evidence discovery and extraction
model_policy:
  class: efficient-read-heavy
  default_slot: worker
  reasoning: medium
permission_ceiling:
  filesystem: worktree-write
  network: search-and-fetch
  external_write: forbidden
  allowed_roots: [work]
allowed_tool_capabilities: [web-search, document-read, citation-resolve]
default_context_policy: isolated-task
delegation:
  allowed: false
output_contracts: [evidence-record, handoff-packet]
```

Profile 不包含完整 Skill 指令，也不固定厂商模型。`default_slot` 只在小型本地模型池中指向 `primary`、
`worker` 或一个显式 specialist；Task/人类可以在形成 frozen execution input 前覆盖它。View 冻结后若
需要更换 slot、Model、Provider、Runtime 或 Host，必须重新形成并验证 execution binding/View，不能由
Host 触发自动评分、静默 fallback 或 local rebind。

## 4. 首批 Agent Profiles

### coordinator

主 Agent 配置。最小工具集，读取 Main State、Task/Handoff 索引和短摘要。默认不读取 raw materials。

### evidence-scout

源材料只读、任务区受限写的检索密集 Agent。允许搜索、文档阅读、引用解析并写自己的 Task 工件；禁止修改正式 Claim、其他 Task、上传本地敏感材料或生成最终综合结论。路径权限语义见 [ADR-0017](../decisions/0017-SCOPED-WRITE-PERMISSIONS.md)。

### simulation-auditor

受限计算 Agent。允许读取代码、参数、Run 工件，并在任务工作区执行检查；禁止修改基准 Run、改变模型假设或批准误差范围。

### targeted-reviewer

默认只读的专项审查 Agent。必须携带一个具体风险问题和停止条件，不能执行“全面复核一切”。

## 5. 委派准入

只有满足至少一项时才委派：

- 存在两个以上真正独立的读取或分析通道；
- 中间输出会显著污染主上下文；
- 需要与主 Agent 不同的 Skill 或工具边界；
- 高风险结果需要一次独立、定向复核；
- 任务运行时间较长且可以隔离。

以下情况默认不委派：

- 单一、短小、主 Agent 已有全部上下文的任务；
- 需要频繁共享隐式状态的紧耦合写入；
- 子 Agent 产出无法形成独立工件；
- 协调成本可能高于执行成本。

委派后，子 Agent 可以先发现路径、文件名、大小、版本与哈希等元数据；读取允许集之外的正文必须请求扩展并记录原因。普通返回使用 H1 Compact Handoff；只有风险、压缩、外部副作用、promotion、争议或 Task 明确要求时才升级为 H2 审计链。

## 6. 递归委派

默认 `max_delegation_depth: 1`。子 Agent 不得再创建子 Agent，除非 Task Packet 同时声明：

- `delegation.allowed: true`；
- 最大深度、最大并发和子预算；
- 可委派的子问题类型；
- 汇总责任与失败处理。

任何递归委派都必须返回一份合并后的 Handoff，而不是把完整子树抛给主 Agent。

## 7. 当前 Core 执行映射

当前 M11 Core 的启动边界不是 `Task + Skill Assignment`，而是：
# Thin Execution Host

M11-003 实现一个 supply-neutral、single-binding、single-attempt 的窄 Host：

```text
hash-pinned Resolved Execution View（内部绑定 exact Runtime Bundle）
  ↓ deterministic View recomputation
one pre-bound FrozenExecutionDriver
  ↓ exactly one call
Execution Host Fact Report
```

Host 不接收候选 Driver 列表，不访问模型池，不选择 Provider/Tool，也没有 retry/fallback/recovery loop。

## View consumer

`load_resolved_execution_view()` 要求单个 View 文件、external SHA-256 pin 和已验证 Runtime Bundle。它会：

- schema-check View；
- 校验 View→Runtime Bundle identity/path/hash；
- 从 View 中恢复 Profile、DataPolicy、Host policy、Execution Binding 的 exact pins；
- 调用 M11-002 producer 作确定性重算，并要求结果逐字段相等；
- 返回深层只读 `ValidatedExecutionView`，其中保留这次重算使用的 exact `ValidatedRuntimeBundle`。

因此，即使攻击者重写 View 并同步更新文件 hash，也不能静默修改 Model、Host、policy intersection 或
frozen Supply selection。任何上游 policy/binding 文件漂移也会在重算前被各自 hash pin 阻断。执行 API
不再接受第二个可替换 Bundle 参数；在 Driver 调用前，Host 会按 View 绑定的 manifest pin 重载 manifest 与
全部 document，并与已验证 Bundle 比较，从而在可控文件边界内阻断 validate/use 间的 Bundle 漂移。

## Driver port

`FrozenExecutionDriver` 只有两个 surface：

- `binding`：Driver 声明自己实际使用的 Provider/Adapter/Model/Runtime/Host identity；
- `execute(FrozenExecutionRequest)`：接收只读 View 与 bundle documents，返回 `ExecutionDriverResult`。

Host 在调用前要求 Driver binding 与 View 完全一致，并由 Host 自有 `SystemHostClock` 或测试注入的 trusted
`HostClock` 观察 start/end；执行调用方不能提交或回填时间戳。Host-observed `started_at` 必须仍落在冻结的 Supply、
DataPolicy 与 Host-policy 三组有效期内；不一致或过期则零调用、`blocked`，并输出指向当前 Snapshot/View
的 re-resolution request。`actual_facts.elapsed_seconds` 由 Host 的 end-start observation 计算，`max_seconds`
也只使用该 Host-observed duration；Driver 的同名自报值不参与预算授权。调用后仍比较 actual binding，检测
Driver 静默 rebind。

## Boundary enforcement 与 facts

Driver 必须报告：

- turns、output tokens、Provider/Tool invocation counts 与实际 Tool identity 集合；Driver 可携带 elapsed
  observation，但 Host report 与 `max_seconds` enforcement 不信任该值；
- external write、data-egress payload classes、side effects；
- output artifacts 的 contract/path/hash；
- fact capture 是否完整及 capture gaps。

Host report 明确区分两类 enforcement：

- `preventive_controls`：Driver 调用前可判定的 exact binding、freshness 与 Runtime Bundle integrity；失败时
  Driver 零调用，因此可称 prevented；
- `detective_controls`：调用返回后对 actual binding、事实完整性、external write、egress、side effects、
  budget、artifact scope 与 outputs 的核对；这些只能称 detected，不能声称外部副作用已被沙箱阻止。

越界、缺失 output、artifact path/hash 漂移或事实捕获缺口均转为 `failed`，不会写成 completion。
`driver_claims_trusted: false` 明确 Driver 自报事实仍需 Trace/Receipt 后续闭合。Driver exception 只产生
content-free `HOST-DRIVER-EXCEPTION` 与 `driver-exception` capture gap；异常正文不会进入 report，Host 也
不会重试。

## Report 不是 Receipt

`execution_host_report` 固定本次 `runtime_bundle_ref`、View、Task 与 exact Action/Capability slice，并把
`requested_binding`/`requested_supply_report_ref` 和调用后的 actual facts 分开：preflight 零调用时没有
actual binding；post-call 成功或失败都保留 Driver 返回的 actual binding/Supply；driver exception 也不伪造
actual binding。其 boundary 固定：

- `actual_facts_only: true`；
- 不拥有 Supply selection、rebinding、automatic fallback；
- 不产生 Method decision、Claim effect 或 Human decision；
- 不实现 Topic 5 recovery。
- 不宣称 whole-Task completion。

失败时可包含 bounded Diagnostic。只有 binding 需要变化时才生成 re-resolution request；这不是 Host 自己
执行 re-resolution。M11-004 才把 fact report 连接到通用 Trace/Artifact/Validation/Receipt。

## 当前适用范围

测试使用 bounded local no-Skill procedure Driver，证明接口与边界，不证明任何真实 Provider 账号、模型、
SDK、网络调用或 OS 级副作用隔离可用。TOCTOU 防线覆盖受 pin 的仓库文件重载，不等同于锁定外部服务状态。
现有 M6 Provider/session 可以在后续通过薄 Driver 适配，但 M11-003 不修改其 SDK、认证或 live conformance。
